const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.trim().toLowerCase().replace(/[’‘]/g,"'").replace(/[.!?]+$/,'').replace(/\s+/g,' ');
const searchNorm=s=>norm(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const main=$('#main');
$('#nav').innerHTML=`<a href="#accueil" data-page="accueil"><span>⌂</span> Sommaire</a><a href="#verbes" data-page="verbes"><span>Aa</span> Répertoire des verbes</a>`+modules.map((m,i)=>`<a href="#${m.id}" data-page="${m.id}" class="${i===0?'nav-break':''}"><span>${m.n}</span>${m.title}</a>`).join('')+`<a class="nav-break" href="#test" data-page="test"><span>↗</span> Repères pour le test</a>`;
$('#menu').onclick=()=>{document.body.style.setProperty('--topbar-h',$('.topbar').getBoundingClientRect().bottom+'px');const open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',open)};
function closeMenu(){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false')}
function cards(lesson='all'){
 const groups=[['01','Les temps',['present','pc','imparfait','choisir','pqp']],['02','Les pronoms',['pronoms','yen','place']],['03','Les mots utiles',['reperes','expressions']]];
 return groups.map(([number,title,ids])=>{const list=ids.map(id=>modules.find(m=>m.id===id)).filter(m=>lesson==='all'||m.lessons.includes(+lesson));return list.length?`<section class="notebook-chapter"><span class="chapter-number" aria-hidden="true">${number}</span><div class="chapter-content"><h2>${title}</h2><ul>${list.map(m=>`<li><a href="#${m.id}"><span class="toc-text"><span class="toc-title">${m.title}</span><small>${m.subtitle}</small></span><span class="toc-leader" aria-hidden="true"></span><span class="toc-n" aria-hidden="true">${m.n}</span></a></li>`).join('')}</ul></div></section>`:''}).join('');
}
function home(){main.innerHTML=`<div class="notebook"><header class="notebook-header"><p class="eyebrow">B1− · cours 1 à 8</p><h1>Mon carnet de français</h1><p class="lede">Les temps, les pronoms et les mots utiles, fiche par fiche.</p><div class="notebook-meta"><span>Afficher :</span><label class="filter-label"><span class="sr-only">Filtrer par cours</span><select id="lesson-filter" aria-label="Filtrer par cours"><option value="all">Tous les cours</option>${Array.from({length:8},(_,i)=>`<option value="${i+1}">Cours ${i+1}</option>`).join('')}</select></label></div></header><div id="cards">${cards()}</div><a class="notebook-reference" href="#verbes"><svg viewBox="0 0 28 24" aria-hidden="true"><path d="M14 5C10 2 5 2 2 3v17c4-1 8-1 12 2 4-3 8-3 12-2V3c-3-1-8-1-12 2Zm0 0v17" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg><span>Répertoire des verbes<small>27 verbes, 4 temps et les participes passés</small></span><span aria-hidden="true">›</span></a><a class="notebook-exam" href="#test">Préparer le test final →</a></div>`;$('#lesson-filter').onchange=e=>$('#cards').innerHTML=cards(e.target.value)}
function questionHTML(q,i){const [before,after]=q[0].includes('___')?q[0].split('___'):[q[0],null];const n=`<span class="n">${i+1}.</span>`;
 if(q[3])return `<div class="question"><p>${n}${esc(before)}${after!==null?'<span class="blank" aria-hidden="true">&nbsp;?&nbsp;</span>'+esc(after):''}</p><div class="choices" role="group" aria-label="Choix ${i+1}" data-index="${i}">${q[3].map(o=>`<button type="button">${esc(o)}</button>`).join('')}</div><p class="feedback" aria-live="polite"></p></div>`;
 const input=`<input class="blank${after===null?' wide':''}" aria-label="Réponse ${i+1}" autocomplete="off" spellcheck="false" autocapitalize="none" size="${Math.max(6,q[1].split('|')[0].length+2)}">`;
 return `<form class="question" data-index="${i}"><p>${n}${esc(before)}${after!==null?input+esc(after):''}</p>${after===null?input:''}<div class="answer-row"><button type="submit">Vérifier</button><button type="button" class="reveal">Voir la réponse</button></div><p class="feedback" aria-live="polite"></p></form>`}
function modulePage(m){main.innerHTML=`<a class="back" href="#accueil">← Sommaire</a><header class="page-header"><p class="eyebrow">Fiche ${m.n} · ${m.tag.toLowerCase()}</p><h1>${m.title}</h1><p>${m.intro}</p><div class="chips">${m.lessons.map(l=>`<span class="chip">cours ${l}</span>`).join('')}</div></header><div class="lesson-layout"><article class="lesson-body">${m.sections.map((s,i)=>`<section class="content-section" id="section-${i}"><h2>${s[0]}</h2>${s[1]}</section>`).join('')}<details lang="en"><summary>English clarification</summary><p>${m.en}</p></details>${m.q.length?`<section class="practice"><h2>À toi !</h2><p>Les accents comptent, pas les majuscules.</p>${m.q.map(questionHTML).join('')}</section>`:''}<p class="source"><b>Sources et périmètre.</b> ${m.source}</p><div class="bottom-band"><a href="#${modules[(modules.indexOf(m)+1)%modules.length].id}">${modules[(modules.indexOf(m)+1)%modules.length].title} →</a><button class="btn" onclick="window.print()">Imprimer cette fiche</button></div></article><aside class="lesson-toc"><p class="eyebrow">Dans cette fiche</p>${m.sections.map((s,i)=>`<a href="#${m.id}" data-scroll="section-${i}">${s[0]}</a>`).join('')}<a href="#verbes">Répertoire des verbes ↗</a></aside></div>`;
main.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll).scrollIntoView({behavior:'smooth'})});
main.querySelectorAll('form.question').forEach(f=>{const q=m.q[+f.dataset.index],input=f.querySelector('input'),feedback=f.querySelector('.feedback');f.onsubmit=e=>{e.preventDefault();if(!input.value.trim()){feedback.className='feedback';feedback.textContent='Écris une réponse avant de vérifier.';return}const ok=q[1].split('|').some(a=>norm(a)===norm(input.value));feedback.className='feedback '+(ok?'success':'review');feedback.textContent=ok?'✓ Oui. '+q[2]:'Pas encore. Relis la règle, puis réessaie.'};f.querySelector('.reveal').onclick=()=>{feedback.className='feedback';feedback.textContent='Réponse : '+q[1].split('|')[0]+'. '+q[2]}});
main.querySelectorAll('.choices').forEach(g=>{const q=m.q[+g.dataset.index],feedback=g.nextElementSibling;g.querySelectorAll('button').forEach(b=>b.onclick=()=>{const ok=b.textContent===q[1];b.classList.add(ok?'right':'wrong');feedback.className='feedback '+(ok?'success':'review');feedback.textContent=ok?'✓ Oui. '+q[2]:'Pas celle-ci. Essaie encore.'})})}
function conjugated(v,tense){const p=v[1].split(','),reflexive=v[0]==='s’appeler';if(tense==='present')return p;if(tense==='imparfait'){if(v[0]==='être')return ['étais','étais','était','étions','étiez','étaient'];const stem=reflexive?'appel':p[3].slice(0,-3);return ['ais','ais','ait','ions','iez','aient'].map((end,i)=>{let s=stem;if(v[0]==='manger'&&(i===3||i===4))s='mang';let word=s+end;if(reflexive){const r=['m’','t’','s’','nous ','vous ','s’'][i];word=r+word}return word})}const etre=v[3]==='être';let aux=tense==='pc'?(etre?['suis','es','est','sommes','êtes','sont']:['ai','as','a','avons','avez','ont']):(etre?['étais','étais','était','étions','étiez','étaient']:['avais','avais','avait','avions','aviez','avaient']);return aux.map((a,i)=>{let pp=v[2]+(etre?(i===3||i===4||i===5?'s':''):'');if(reflexive){let r=['me ','te ','se ','nous ','vous ','se '][i];if(/^[aeé]/.test(a))r=['m’','t’','s’','nous ','vous ','s’'][i];a=r+a}return a+' '+pp})}
function verbPage(selected){main.innerHTML=`<a class="back" href="#accueil">← Sommaire</a><div class="verb-panel"><header class="page-header compact"><div><p class="eyebrow">Répertoire des verbes · 27 verbes, 4 temps</p><h1>Conjugaison</h1></div><div class="verb-tools"><label>Le verbe<select id="verb">${verbs.map((v,i)=>`<option value="${i}">${v[0]}</option>`).join('')}</select></label></div></header><div id="verb-output"></div><section class="content-section"><h2>Les participes passés, à l’oreille</h2><p>Comme dans le rappel du cours 1, les participes sont rangés par le son final. Au féminin, on entend parfois la consonne : <b>prise, mise, écrite, faite</b>.</p><div class="pp-grid">${participleGroups.map(([sound,note,list])=>`<section><h3>-${sound}${note?`<small>${note}</small>`:''}</h3><ul>${list.map(([inf,pp,extra])=>`<li${extra?' class="extra"':''}><span>${inf}</span><b>${pp}</b></li>`).join('')}</ul></section>`).join('')}</div><p class="muted">° Rencontré dans les récits et les devoirs. Falloir et pleuvoir s’emploient avec il : il a fallu, il a plu. L’auxiliaire dépend de la construction : elle est sortie, mais elle a sorti son sac.</p></section><p class="source">Sources : Cours 1 · verbes_frequents_indicatif_present.pdf, p. 1 ; Le passé composé RAPPEL.docx ; Cours 2 et 8 pour les règles de formation. Les tableaux aux autres temps sont générés à partir de ces règles.</p></div>`;if(selected){const i=verbs.findIndex(v=>v[0]===selected);if(i>=0)$('#verb').value=i}$('#verb').onchange=()=>{history.replaceState(null,'','#verbes/'+encodeURIComponent(verbs[+$('#verb').value][0]));drawVerb()};drawVerb()}
function drawVerb(){const v=verbs[+$('#verb').value],pronouns=['je','tu','il / elle / on','nous','vous','ils / elles'],tenses=[['present','Présent'],['imparfait','Imparfait'],['pc','Passé composé'],['pqp','Plus-que-parfait']];
 const block=([t,label])=>`<section class="tense-block"><h3>${label}</h3><ul>${conjugated(v,t).map((f,i)=>`<li>${i===0&&/^[aeéiou]/.test(f)?`<span>j’</span><b>${f}</b>`:`<span>${pronouns[i]}</span> <b>${f}</b>`}</li>`).join('')}</ul></section>`;
 $('#verb-output').innerHTML=`<div class="verb-card"><div class="verb-title"><h2>${v[0]}</h2><div class="meta-row"><div><small>Participe passé</small><b>${v[2]}</b></div><div><small>Auxiliaire</small><b>${v[3]||'avoir'}</b></div></div></div><div class="tense-blocks">${tenses.map(block).join('')}</div></div>${v[3]==='être'?'<div class="warning">Temps composés au masculin ; nous, vous et ils au pluriel. Au féminin, ajoute e : elle est venue, elles étaient venues. Pour vous de politesse, accorde avec la personne : vous êtes venu / venue.</div>':''}${v[0]==='s’appeler'?'<p class="muted">Au passé, ces formes signifient « se nommer » (il s’est appelé Paul) ou « s’appeler l’un l’autre » (nous nous sommes appelés). Pour présenter son nom, utilise normalement le présent.</p>':''}${v[0]==='être'?'<p class="muted">Être utilise avoir aux temps composés : j’ai été, j’avais été.</p>':''}`}
function exam(){main.innerHTML=`<a class="back" href="#accueil">← Sommaire</a><header class="page-header"><p class="eyebrow">Examen final</p><h1>Préparer le test</h1><p>Ce carnet résume les cours 1 à 8. Il ne prétend pas couvrir tout le programme ni prédire les questions du test final.</p></header><div class="exam-grid"><section><h2>Une révision en 15 min</h2><p><b>3 min :</b> rappelle une règle sans la lire.</p><p><b>5 min :</b> compare les exemples de la fiche.</p><p><b>4 min :</b> réponds aux questions puis vérifie.</p><p><b>3 min :</b> invente deux phrases dans un autre contexte.</p><a class="btn primary" href="#choisir">Commencer par les temps</a></section><section><h2>Les priorités du carnet</h2><ul><li>Former les temps et choisir le bon passé.</li><li>Connaître les verbes fréquents et leurs participes.</li><li>Choisir et placer COD, COI, y et en.</li><li>Distinguer les repères temporels.</li><li>Réutiliser ces structures dans un court récit.</li></ul><p class="muted">Priorités fondées sur les exercices du cours, pas sur une liste officielle des questions d’examen.</p></section><section><h2>Le format confirmé</h2><p><b>Écrit : 1 h 45, sur 50 points.</b> Grammaire, conjugaison, vocabulaire, lecture, rédaction et compréhension orale.</p><p><b>Oral : rendez-vous de 15 min, sur 50 points.</b> 7 min de préparation et 5 à 6 min de monologue et interaction.</p><p><b>Réussite : 60 / 100.</b> Aucun exercice d’écoute n’est intégré à ce carnet.</p></section><section><h2>Ce que l’oral demande</h2><p>Présenter un document, expliquer avantages et inconvénients, donner son opinion et des exemples, puis répondre aux questions.</p><p>La grille valorise notamment une prise de parole d’au moins 3 minutes et des idées reliées logiquement. Elle évalue aussi le vocabulaire, les structures et conjugaisons, la capacité à reformuler et une prononciation intelligible.</p><a class="btn" href="#expressions">Ouvrir le mémo de phrases</a></section></div><section class="content-section"><h2>Passer des règles à un texte</h2><details><summary>Trois tâches courtes, sans correction automatique</summary><p><b>Parcours :</b> écris au moins 100 mots sur tes études et tes expériences, puis ta situation actuelle.</p><p><b>Récit :</b> écris au moins 100 mots sur un imprévu. Installe le contexte à l’imparfait, raconte les événements au passé composé et explique un fait antérieur au plus-que-parfait si nécessaire.</p><p>Les devoirs 1 et 2 demandent 100 mots minimum ; ce seuil n’est pas une consigne confirmée pour la rédaction du test. Le devoir 2 porte sur PC / imparfait ; le plus-que-parfait est ici un prolongement des cours 7–8.</p><p><b>Lecture :</b> reprends un récit du cours. Repère qui fait quoi, les dates, la chronologie et les mots repris par les pronoms. Résume-le ensuite en trois phrases.</p><p>Relis les auxiliaires, les accords, les pronoms et les connecteurs. Ces productions libres ne sont pas évaluées par le carnet.</p></details></section><details><summary>Sources, limites et suivi</summary><p>Fondé sur french_course_syllabus_v1.md (17 octobre 2026), les fiches fournies des cours 1 à 8 et B1- EXAMEN.docx. Les explications et les exercices sont reformulés ; les compléments de référence sont signalés.</p><p>Le document d’examen donne une note globale d’oral sur 50 et une grille séparée sur 20, sans expliquer leur correspondance. Les thèmes exacts de l’examen ne sont pas confirmés.</p><p>Les points seulement annoncés dans le programme, comme le subjonctif ou le futur antérieur, ne sont pas inclus. De nouveaux cours pourront enrichir les fiches.</p><p>Les réponses ici sont des essais d’entraînement. Elles ne sont pas sauvegardées et ne mesurent pas la rétention. Le tableau de progression reste le registre des évaluations faites en séance.</p></details><p class="source">Examen : B1- EXAMEN.docx, pp. 1–4. Ce site ne contient ni enregistrement ni exercice d’écoute.</p>`}
function route(){const parts=location.hash.slice(1).split('/'),id=parts[0]||'accueil';closeMenu();$('#results').hidden=true;$('#search').value='';document.querySelectorAll('#nav a').forEach(a=>{const active=a.dataset.page===id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});let m=modules.find(x=>x.id===id);if(m)modulePage(m);else if(id==='verbes')verbPage(parts[1]?decodeURIComponent(parts[1]):null);else if(id==='test')exam();else home();document.title=(m?m.title:id==='verbes'?'Les verbes':id==='test'?'Préparer le test':'Révisions B1−')+' · Français B1−';window.scrollTo(0,0)}
$('#search').oninput=e=>{const q=searchNorm(e.target.value);const r=$('#results');if(!q){r.hidden=true;return}const matches=modules.filter(m=>searchNorm(m.title+' '+m.subtitle+' '+m.sections.map(s=>s.join(' ')).join(' ')).includes(q));const vv=verbs.filter(v=>searchNorm(v.join(' ')).includes(q));r.innerHTML=matches.slice(0,6).map(m=>`<a href="#${m.id}">${m.title}<small>${m.subtitle}</small></a>`).join('')+vv.slice(0,5).map(v=>`<a href="#verbes/${encodeURIComponent(v[0])}">${v[0]}<small>Conjugaison · participe ${v[2]}</small></a>`).join('');if(!r.innerHTML)r.innerHTML='<p>Aucun résultat. Essaie « passé », « depuis » ou « prendre ».</p>';r.hidden=false};
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#results').hidden=true;if(e.target.closest('#results a')){$('#results').hidden=true;$('#search').value=''}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();$('#results').hidden=true}});window.addEventListener('hashchange',route);route();
$('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView()};
